#!/bin/bash
# db-migrate.sh — Apply ɳTasks PostgreSQL schema + migrations idempotently
#
# Purpose:
#   Applies postgres/init.sql (base np_* application schema) then
#   postgres/migrations/*.sql (in numeric order) against the running Postgres
#   container. Tracks applied files in a schema_migrations table so re-runs
#   are safe.
#
#   NOTE: postgres/init.sql is NOT mounted into docker-entrypoint-initdb.d —
#   only postgres/init/*.sql (schema/extension/auth-helper scaffolding) is
#   (see backend/docker-compose.yml, generated by `nself build`). This script
#   is what actually applies init.sql's np_profiles/np_todos/np_lists tables,
#   so `make db-migrate` (or this script directly) MUST be run once after
#   the stack is first brought up — `make up` alone does not create the app
#   tables. See backend/Makefile `up` target which runs seed-dev.sh after
#   `nself start`; db-migrate should run before/alongside that on first boot.
#
# Usage:
#   bash scripts/db-migrate.sh            # normal run
#   POSTGRES_DB=nself bash scripts/db-migrate.sh
#
# Inputs:
#   POSTGRES_USER  (default: postgres)
#   POSTGRES_DB    (default: from .env, else ntask)
#   POSTGRES_CONTAINER (default: <PROJECT_NAME>_postgres, from .env)
#
# The container name and database used to default to `backend_postgres` and
# `nself`, neither of which anything produces: `nself build` names containers
# `${PROJECT_NAME}_postgres` and this project's database is `ntask`. So
# `make migrate` failed on every fresh checkout with "PostgreSQL did not become
# ready" — a timeout message for a container that was healthy the whole time and
# simply had a different name (found by the 2026-08-24 fork drill).
#
# Constraints:
#   - Requires docker compose stack to be UP (postgres container running)
#   - Runs as the postgres superuser inside the container (no pg_cron needed)
#   - All migration SQL must be idempotent (CREATE IF NOT EXISTS, DROP IF EXISTS, etc.)

set -euo pipefail

BACKEND_DIR="$(cd "$(dirname "$0")/.." && pwd)"

# Read the project's own configuration rather than guessing names. Only the three
# keys this script needs are read, and they are read with grep rather than by
# sourcing the file: .env legitimately contains values with shell metacharacters
# (the shipped example has `https://<account-id>.r2.cloudflarestorage.com`), and
# sourcing it turns those into redirections. Values already in the environment
# win, so a caller can still override any of them.
env_value() {
  local key="$1" file
  for file in "$BACKEND_DIR/.env" "$BACKEND_DIR/.env.dev"; do
    [ -f "$file" ] || continue
    local line
    line=$(grep -m1 -E "^[[:space:]]*${key}=" "$file" 2>/dev/null) || continue
    line="${line#*=}"
    line="${line%\"}"; line="${line#\"}"
    line="${line%\'}"; line="${line#\'}"
    printf '%s' "${line%%[[:space:]]#*}"
    return 0
  done
}

PROJECT="${PROJECT_NAME:-$(env_value PROJECT_NAME)}"
PROJECT="${PROJECT:-$(env_value NSELF_PROJECT_NAME)}"
PROJECT="${PROJECT:-ntask}"
PG_USER="${POSTGRES_USER:-$(env_value POSTGRES_USER)}"
PG_USER="${PG_USER:-postgres}"
PG_DB="${POSTGRES_DB:-$(env_value POSTGRES_DB)}"
PG_DB="${PG_DB:-ntask}"
PG_CONTAINER="${POSTGRES_CONTAINER:-${PROJECT}_postgres}"

if ! docker ps --format '{{.Names}}' | grep -qx "$PG_CONTAINER"; then
  echo "[db-migrate] [ERROR] no running container named '$PG_CONTAINER'." >&2
  echo "[db-migrate] Running postgres containers:" >&2
  docker ps --format '{{.Names}}' | grep postgres >&2 || echo "  (none)" >&2
  echo "[db-migrate] Set POSTGRES_CONTAINER=<name> or PROJECT_NAME=<project> and retry." >&2
  exit 1
fi
INIT_SQL="$BACKEND_DIR/postgres/init.sql"
MIGRATIONS_DIR="$BACKEND_DIR/postgres/migrations"

# ---- helpers ----------------------------------------------------------------

psql_exec() {
  docker exec -i "$PG_CONTAINER" psql -U "$PG_USER" -d "$PG_DB" -v ON_ERROR_STOP=1 "$@"
}

psql_file() {
  local file="$1"
  docker exec -i "$PG_CONTAINER" psql -U "$PG_USER" -d "$PG_DB" \
    -v ON_ERROR_STOP=1 \
    --single-transaction \
    -f /dev/stdin < "$file"
}

log() { echo "[db-migrate] $*"; }
ok()  { echo "[db-migrate] [ok] $*"; }
err() { echo "[db-migrate] [ERROR] $*" >&2; exit 1; }

# ---- wait for postgres -------------------------------------------------------

log "Waiting for PostgreSQL to accept connections..."
WAIT=0
until docker exec "$PG_CONTAINER" pg_isready -U "$PG_USER" -q 2>/dev/null; do
  WAIT=$((WAIT + 1))
  [ "$WAIT" -ge 30 ] && err "PostgreSQL did not become ready after 30s. Is the stack up?"
  sleep 1
done
ok "PostgreSQL ready."

# ---- ensure tracking table --------------------------------------------------

log "Ensuring schema_migrations tracking table..."
psql_exec -c "
CREATE TABLE IF NOT EXISTS public.schema_migrations (
  filename   TEXT        PRIMARY KEY,
  applied_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
" > /dev/null

# ---- apply auth.uid() helper (must precede all RLS policies) ----------------
# This function is not in the docker init/ scripts; we inject it here so that
# RLS policies in init.sql and all migrations can call auth.uid() correctly.

log "Ensuring auth.uid() helper function..."
psql_exec -c "
CREATE SCHEMA IF NOT EXISTS auth;
CREATE OR REPLACE FUNCTION auth.uid()
RETURNS uuid LANGUAGE sql STABLE AS \$\$
  SELECT NULLIF(
    current_setting('hasura.user', true)::json ->> 'x-hasura-user-id',
    ''
  )::uuid
\$\$;
GRANT EXECUTE ON FUNCTION auth.uid() TO PUBLIC;
" > /dev/null
ok "auth.uid() ready."

# ---- apply init.sql (base schema) -------------------------------------------
# init.sql defines the foundational np_* tables. The nSelf docker init/
# directory (postgres/init/*.sql) handles schema + extension setup on first
# container launch. init.sql defines the APPLICATION tables and is also
# idempotent (all CREATE IF NOT EXISTS). We skip it when the base tables are
# already present (Docker init/ already ran them) to avoid FK-constraint
# ordering errors. We apply it only on a truly empty DB (fresh install without
# the nSelf init/ scripts having run, e.g. a bare postgres container in CI).

TABLES_EXIST=$(psql_exec -tAc \
  "SELECT COUNT(*) FROM pg_tables WHERE schemaname='public' AND tablename='np_profiles';" \
  2>/dev/null || echo "0")
TABLES_EXIST="${TABLES_EXIST// /}"

if [ "$TABLES_EXIST" = "0" ] && [ -f "$INIT_SQL" ]; then
  log "np_profiles not found — applying postgres/init.sql (fresh DB: $PG_DB)..."
  # init.sql has no \c/hardcoded db name — always apply against $PG_DB
  # explicitly so this works regardless of POSTGRES_DB (see incident: a
  # previous hardcoded \c nself in postgres/init/*.sql broke auth.uid()/RLS
  # on staging where POSTGRES_DB=ntask).
  docker exec -i "$PG_CONTAINER" psql -U "$PG_USER" -d "$PG_DB" -v ON_ERROR_STOP=1 < "$INIT_SQL" \
    || err "postgres/init.sql failed. Check the output above."
  ok "postgres/init.sql applied."
else
  log "Base tables already present (init/ scripts ran) — skipping postgres/init.sql."
fi

# ---- apply numbered migrations in order ------------------------------------

shopt -s nullglob
MIGRATION_FILES=("$MIGRATIONS_DIR"/[0-9][0-9][0-9]_*.sql)
shopt -u nullglob

if [ "${#MIGRATION_FILES[@]}" -eq 0 ]; then
  log "No migration files found in $MIGRATIONS_DIR — nothing to apply."
  exit 0
fi

APPLIED=0
SKIPPED=0
FAILED=0

for FILEPATH in "${MIGRATION_FILES[@]}"; do
  FILENAME="$(basename "$FILEPATH")"

  # Skip down migrations
  if [[ "$FILENAME" == *.down.sql ]]; then
    continue
  fi

  # Check if already applied
  ALREADY=$(psql_exec -tAc "SELECT COUNT(*) FROM public.schema_migrations WHERE filename = '$FILENAME'" 2>/dev/null || echo "0")
  ALREADY="${ALREADY// /}"  # trim whitespace

  if [ "$ALREADY" != "0" ]; then
    SKIPPED=$((SKIPPED + 1))
    continue
  fi

  log "Applying $FILENAME ..."
  if psql_file "$FILEPATH"; then
    psql_exec -c "INSERT INTO public.schema_migrations (filename) VALUES ('$FILENAME') ON CONFLICT DO NOTHING;" > /dev/null
    ok "$FILENAME applied."
    APPLIED=$((APPLIED + 1))
  else
    FAILED=$((FAILED + 1))
    err "Migration $FILENAME FAILED. Stack left at last good state. Fix the SQL and re-run."
  fi
done

echo ""
log "Migration run complete: ${APPLIED} applied, ${SKIPPED} already applied, ${FAILED} failed."

if [ "$FAILED" -gt 0 ]; then
  exit 1
fi
